import { readdirSync, readFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';

// Regression guard: scaffolded sections reuse the captured class strings, which
// reference CSS custom properties. Every var(--x) used in the captured HTML (and
// footer.json) must resolve: defined inline in the same HTML, defined in
// app/globals.css, or generated by Tailwind itself.

const ROOT = join(__dirname, '..', '..');
const REF = join(ROOT, 'reference');
const globals = readFileSync(join(ROOT, 'app/globals.css'), 'utf8');

// Tailwind v4 generates these from its default theme / utilities; nothing to define.
const TAILWIND_GENERATED =
  /^--(?:font-(?!heading$|sans$)|breakpoint-|spacing$|text-(?!default$|secondary$|muted$)|radius-|shadow-|inset-shadow-|drop-shadow-|default-|tw-|ease-|animate-|tracking-|leading-|blur-|container-|perspective-|aspect-|color-(?:inherit|current|transparent|black|white|(?:red|orange|amber|yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|purple|fuchsia|pink|rose|slate|gray|zinc|neutral|stone)-\d+))/;

function files(): string[] {
  const out: string[] = [];
  for (const page of readdirSync(REF, { withFileTypes: true })) {
    if (!page.isDirectory()) continue;
    const dir = join(REF, page.name, 'sections');
    if (!existsSync(dir)) continue;
    for (const f of readdirSync(dir)) if (f.endsWith('.html')) out.push(join(dir, f));
  }
  out.push(join(REF, 'footer.json'));
  return out;
}

const usesIn = (s: string) => new Set([...s.matchAll(/var\(\s*(--[A-Za-z0-9_-]+)/g)].map((m) => m[1]));
const definesIn = (s: string) =>
  new Set([...s.matchAll(/(?:^|[\s;"'{\\])(--[A-Za-z0-9_-]+)\s*:/g)].map((m) => m[1]));

describe('CSS custom properties used by captured markup', () => {
  const all = files();

  it('scans a non-trivial number of captured files', () => {
    expect(all.length).toBeGreaterThan(30);
  });

  it('emits all theme tokens as real :root variables (@theme static)', () => {
    // Tailwind v4 prunes unused @theme variables. Captured markup references
    // e.g. var(--color-brand-teal) from inline styles, which Tailwind never
    // sees as a utility, so the tokens must be emitted unconditionally.
    expect(globals).toMatch(/@theme static\s*\{/);
  });

  it('defines every var(--x) used (inline, globals.css, or Tailwind-generated)', () => {
    const inGlobals = definesIn(globals);
    const missing: string[] = [];
    for (const f of all) {
      const src = readFileSync(f, 'utf8');
      const inline = definesIn(src);
      for (const name of usesIn(src)) {
        if (inline.has(name) || inGlobals.has(name) || TAILWIND_GENERATED.test(name)) continue;
        missing.push(`${name}  (used in ${f.slice(ROOT.length + 1)})`);
      }
    }
    expect(missing).toEqual([]);
  });
});
